//! The Rust of Stash.Effort, ported from C# (CodeCoreMorph, D-84).
use codecoremorph_runtime::{Exception, Result};

/// How hard `codec::pack` works at a blob. It crosses the bridge as its `i32` value.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(i32)]
pub enum Effort {
    Fast = 0,
    High = 1,
    Max = 2,
}

impl TryFrom<i32> for Effort {
    type Error = Exception;

    /// C#'s `(Effort)value`: a value outside the enum is what C#'s `Pack` refuses.
    fn try_from(value: i32) -> Result<Effort> {
        match value {
            0 => Ok(Effort::Fast),
            1 => Ok(Effort::High),
            2 => Ok(Effort::Max),
            _ => Err(Exception::argument_out_of_range("effort", "")),
        }
    }
}

//! The bridge of Stash.Codec: the exports its C# façade calls (CodeCoreMorph, D-84).
use super::ccm::{self, ccm_status};
use crate::codec;
use crate::effort::Effort;

/// `Effort` crosses as its `i32` value.
#[unsafe(no_mangle)]
pub extern "C" fn stash_Codec_pack(
    data_bytes: *const u8,
    data_count: i32,
    effort: i32,
    result_bytes: *mut *mut u8,
    result_count: *mut i32,
) -> ccm_status {
    ccm::guard(|| {
        let data = ccm::array(data_bytes, data_count, "data")?;
        let packed = codec::pack(&data, Effort::try_from(effort)?)?;
        ccm::out_array(result_bytes, result_count, &packed)
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn stash_Codec_unpack(
    packed_bytes: *const u8,
    packed_count: i32,
    result_bytes: *mut *mut u8,
    result_count: *mut i32,
) -> ccm_status {
    ccm::guard(|| {
        let packed = ccm::array(packed_bytes, packed_count, "packed")?;
        ccm::out_array(result_bytes, result_count, &codec::unpack(&packed)?)
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn stash_Codec_packed_bound(length: i32, result: *mut i32) -> ccm_status {
