//! The Rust of Stash.Codec, ported from C# (CodeCoreMorph, D-84). K4os's LZ4Codec is liblz4
//! (`native`) and its XXH32/XXH64 the `xxhash-rust` crate (the plan's dependency table): the
//! same blocks and digests, byte for byte, but for an empty input, which K4os packs as no block
//! at all.
use codecoremorph_runtime::{Exception, Result};

use crate::effort::Effort;
use crate::native;

/// The bytes before a packed blob's LZ4 block: its length, little-endian.
pub const HEADER_SIZE: i32 = 4;
const HEADER: usize = HEADER_SIZE as usize;
const LZ4HC_CLEVEL_MAX: i32 = 12;

fn size_of(data: &[u8]) -> Result<i32> {
    i32::try_from(data.len()).map_err(|_| Exception::argument_out_of_range("data", ""))
}

/// Packs `data` as one LZ4 block behind its length.
pub fn pack(data: &[u8], effort: Effort) -> Result<Vec<u8>> {
    let size = size_of(data)?;
    let bound = native::lz4_compress_bound(size);
    let mut packed = vec![0u8; HEADER + usize::try_from(bound).unwrap_or(0)];
    packed[..HEADER].copy_from_slice(&size.to_le_bytes());
    let target = &mut packed[HEADER..];
    // K4os writes no block for nothing; liblz4 would write one byte.
    let written = match (size, effort) {
        (0, _) => 0,
        (_, Effort::Fast) => native::lz4_compress_default(data, target),
        (_, Effort::High) => native::lz4_compress_hc(data, target, 9),
        (_, Effort::Max) => native::lz4_compress_hc(data, target, LZ4HC_CLEVEL_MAX),
    };
    if written < 0 || (size != 0 && written == 0) {
        return Err(Exception::invalid_operation("LZ4 couldn't encode the blob."));
    }
    packed.truncate(HEADER + usize::try_from(written).unwrap_or(0));
    Ok(packed)
}

fn invalid_data(message: impl Into<String>) -> Exception {
    Exception::new("System.IO.InvalidDataException", message)
}

/// The blob [`pack`] packed.
pub fn unpack(packed: &[u8]) -> Result<Vec<u8>> {
    let Some((header, block)) = packed.split_first_chunk::<HEADER>() else {
        return Err(invalid_data("A packed blob starts with its length."));
    };
    let length = i32::from_le_bytes(*header);
    let Ok(capacity) = usize::try_from(length) else {
        return Err(invalid_data("A packed blob's length can't be negative."));
    };
    let mut data = vec![0u8; capacity];
    // K4os reads no block as nothing; liblz4 refuses an empty one.
    let read = if block.is_empty() { 0 } else { native::lz4_decompress_safe(block, &mut data) };
    if read < 0 {
        return Err(invalid_data("The blob's LZ4 block is corrupt."));
    }
    if read != length {
        return Err(invalid_data(format!(
            "The blob holds {read} bytes, not the {length} its header says."
        )));
    }
    Ok(data)
}

/// The most bytes [`pack`] can make of `length`.
pub fn packed_bound(length: i32) -> Result<i32> {
    if length < 0 {
        return Err(Exception::argument_out_of_range("length", "A length can't be negative."));
    }
    Ok(HEADER_SIZE + native::lz4_compress_bound(length))
}

pub fn checksum(data: &[u8]) -> u64 {
    xxhash_rust::xxh64::xxh64(data, 0)
}

/// A 32-bit checksum of `data`, seeded.
pub fn short_checksum(data: &[u8], seed: u32) -> u32 {
    xxhash_rust::xxh32::xxh32(data, seed)
}

