//! The native libraries the C# called through P/Invoke, which the Rust calls itself
//! (CodeCoreMorph, D-84), and the C libraries that stand for .NET packages (D-95): here
//! liblz4, K4os.Compression.LZ4's counterpart. Each `<library>_sys` holds bindgen's
//! declarations from the library's C headers, written at each configure: never edit it. The
//! safe functions the rest of the crate calls go here, each `unsafe` block with a `// SAFETY:`
//! comment. Besides the bridge, the one module that may hold unsafe code; after the
//! retirement, the only one.

/// bindgen's declarations of lz4 (`lz4_sys.rs`: lz4.h and lz4hc.h), included rather than a
/// module file, so cbindgen, which expands no macro, leaves them out of the bridge's header.
///
/// cbindgen:ignore
#[allow(non_upper_case_globals, non_camel_case_types, non_snake_case, dead_code)]
#[allow(clippy::all)]
pub mod lz4_sys {
    include!("lz4_sys.rs");
}

#[link(name = "lz4")]
unsafe extern "C" {}

use std::ffi::c_char;

/// `LZ4_compressBound`: the most bytes a block of `size` bytes compresses to; 0 for a size
/// LZ4 can't take.
pub fn lz4_compress_bound(size: i32) -> i32 {
    // SAFETY: a pure function of its argument.
    unsafe { lz4_sys::LZ4_compressBound(size) }
}

fn lengths(source: &[u8], target: &[u8]) -> Option<(i32, i32)> {
    Some((i32::try_from(source.len()).ok()?, i32::try_from(target.len()).ok()?))
}

/// `LZ4_compress_default` into `target`: the bytes written, 0 when they don't fit.
pub fn lz4_compress_default(source: &[u8], target: &mut [u8]) -> i32 {
    let Some((size, capacity)) = lengths(source, target) else { return 0 };
    // SAFETY: each pointer is valid for the length passed with it; LZ4 writes at most
    // `capacity` bytes and reads `size`.
    unsafe {
        lz4_sys::LZ4_compress_default(
            source.as_ptr().cast::<c_char>(),
            target.as_mut_ptr().cast::<c_char>(),
            size,
            capacity,
        )
    }
}

/// `LZ4_compress_HC` at `level` into `target`: the bytes written, 0 when they don't fit.
pub fn lz4_compress_hc(source: &[u8], target: &mut [u8], level: i32) -> i32 {
    let Some((size, capacity)) = lengths(source, target) else { return 0 };
    // SAFETY: as lz4_compress_default.
    unsafe {
        lz4_sys::LZ4_compress_HC(
            source.as_ptr().cast::<c_char>(),
            target.as_mut_ptr().cast::<c_char>(),
            size,
            capacity,
            level,
        )
    }
}

/// `LZ4_decompress_safe` into `target`: the bytes written, or a negative number for a
/// malformed block.
pub fn lz4_decompress_safe(source: &[u8], target: &mut [u8]) -> i32 {
    let Some((size, capacity)) = lengths(source, target) else { return -1 };
    // SAFETY: each pointer is valid for the length passed with it; the safe decoder never
    // reads or writes past them, whatever the block holds.
    unsafe {
        lz4_sys::LZ4_decompress_safe(
            source.as_ptr().cast::<c_char>(),
            target.as_mut_ptr().cast::<c_char>(),
            size,
            capacity,
        )
    }
}

