//! The Rust of Stash.Store, ported from C# (CodeCoreMorph, D-84). Its `ILogger` is
//! `codecoremorph_runtime::logging::Logger`, which the C# façade's logger implements through
//! the bridge until the retirement. The store is shared, so its state is behind its own lock,
//! never held while it logs: a C# logger may call back into it.
use std::collections::HashMap;
use std::sync::{Arc, Mutex, MutexGuard};

use codecoremorph_runtime::logging::{self, EventId, LogLevel, Logger, LoggerFactory, NullLogger};
use codecoremorph_runtime::{Exception, Result};

use crate::codec;
use crate::effort::Effort;

#[derive(Clone)]
struct Entry {
    packed: Vec<u8>,
    sum: u64,
}

#[derive(Default)]
struct State {
    entries: HashMap<String, Entry>,
    packed_bytes: i64,
}

impl State {
    fn keep(&mut self, key: &str, entry: Entry) {
        let added = entry.packed.len() as i64;
        if let Some(old) = self.entries.insert(key.to_string(), entry) {
            self.packed_bytes -= old.packed.len() as i64;
        }
        self.packed_bytes += added;
    }
}

/// Blobs by key, kept packed with their checksums.
pub struct Store {
    state: Mutex<State>,
    logger: Arc<dyn Logger>,
    effort: Effort,
}

impl Default for Store {
    fn default() -> Store {
        Store::new(None, Effort::Fast)
    }
}

impl Store {
    /// No logger logs nothing (`NullLogger`), as in C#.
    pub fn new(logger: Option<Arc<dyn Logger>>, effort: Effort) -> Store {
        Store {
            state: Mutex::new(State::default()),
            logger: logger.unwrap_or_else(NullLogger::instance),
            effort,
        }
    }

    /// A store that logs through a logger of `factory`'s.
    pub fn create(factory: Option<&dyn LoggerFactory>, effort: Effort) -> Result<Store> {
        let factory = factory.ok_or_else(|| Exception::argument_null("factory"))?;
        Ok(Store::new(Some(factory.create_logger("Stash.Store")?), effort))
    }

    fn state(&self) -> MutexGuard<'_, State> {
        self.state.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    pub fn count(&self) -> i32 {
        self.state().entries.len() as i32
    }

    /// The packed bytes of every blob, headers included.
    pub fn packed_bytes(&self) -> i64 {
        self.state().packed_bytes
    }

    pub fn put(&self, key: &str, data: &[u8]) -> Result<()> {
        let packed = codec::pack(data, self.effort)?;
        let size = packed.len();
        let sum = codec::checksum(data);
        self.state().keep(key, Entry { packed, sum });
        logging::log_debug(
            &*self.logger,
            "Stored {Key}: {Raw} bytes in {Packed}",
            &[&key, &data.len(), &size],
        )
    }

    fn find(&self, key: &str) -> Result<Entry> {
        self.state()
            .entries
            .get(key)
            .cloned()
            .ok_or_else(|| Exception::key_not_found(format!("No blob is stored under '{key}'.")))
    }

    pub fn get(&self, key: &str) -> Result<Vec<u8>> {
        let entry = self.find(key)?;
        let data = match codec::unpack(&entry.packed) {
            Ok(data) => data,
            Err(e) if e.is("System.IO.InvalidDataException") => {
                logging::log(
                    &*self.logger,
                    LogLevel::Error,
                    &EventId::default(),
                    Some(&e),
                    "Blob {Key} doesn't unpack",
                    &[&key],
                )?;
                return Err(e);
            }
            Err(e) => return Err(e),
        };
        if codec::checksum(&data) != entry.sum {
            logging::log_warning_event(
                &*self.logger,
                &EventId::new(7, "ChecksumMismatch"),
                "Checksum mismatch for {Key}",
                &[&key],
            )?;
            return Err(Exception::new(
                "System.IO.InvalidDataException",
                format!("The blob under '{key}' fails its checksum."),
            ));
        }
        Ok(data)
    }

    pub fn remove(&self, key: &str) -> Result<bool> {
        let left = {
            let mut state = self.state();
            let Some(entry) = state.entries.remove(key) else { return Ok(false) };
            state.packed_bytes -= entry.packed.len() as i64;
            state.entries.len()
        };
        if self.logger.is_enabled(LogLevel::Information)? {
            logging::log_information(&*self.logger, "Removed {Key}; {Count} left", &[&key, &left])?;
        }
        Ok(true)
    }

    /// A blob as it is kept: its packed bytes (a copy), and its checksum.
    pub fn export(&self, key: &str) -> Result<(Vec<u8>, u64)> {
        let entry = self.find(key)?;
        Ok((entry.packed, entry.sum))
    }

    /// Keeps a blob another store exported, unchecked until it is read.
    pub fn import(&self, key: &str, packed: &[u8], checksum: u64) -> Result<()> {
        self.state().keep(key, Entry { packed: packed.to_vec(), sum: checksum });
        logging::log_trace(
            &*self.logger,
            "Imported {Key} ({Packed} bytes)",
            &[&key, &packed.len()],
        )
    }
}

