//! tests/Stash.Tests/CodecTests.cs, translated to Rust (CodeCoreMorph, D-84).
use stash_rs::codec;
use stash_rs::effort::Effort;

fn sentences(length: usize) -> Vec<u8> {
    b"the quick brown fox jumps over the lazy dog. ".iter().copied().cycle().take(length).collect()
}

/// C#'s `new Random(seed).NextBytes`: other bytes from the same kind of source.
fn noise(length: usize, seed: u32) -> Vec<u8> {
    let mut state = seed.wrapping_mul(2_654_435_761) | 1;
    (0..length)
        .map(|_| {
            state ^= state << 13;
            state ^= state >> 17;
            state ^= state << 5;
            state as u8
        })
        .collect()
}

fn sentences_round_trip(length: usize, effort: Effort) {
    let data = sentences(length);
    assert_eq!(data, codec::unpack(&codec::pack(&data, effort).unwrap()).unwrap());
}

#[test]
fn sentences_round_trip_0_fast() {
    sentences_round_trip(0, Effort::Fast);
}

#[test]
fn sentences_round_trip_1_fast() {
    sentences_round_trip(1, Effort::Fast);
}

#[test]
fn sentences_round_trip_100_high() {
    sentences_round_trip(100, Effort::High);
}

#[test]
fn sentences_round_trip_5000_max() {
    sentences_round_trip(5000, Effort::Max);
}

#[test]
fn sentences_round_trip_70000_fast() {
    sentences_round_trip(70000, Effort::Fast);
}

#[test]
fn noise_round_trips_at_every_effort() {
    let data = noise(3000, 17);
    for effort in [Effort::Fast, Effort::High, Effort::Max] {
        let packed = codec::pack(&data, effort).unwrap();
        assert!(packed.len() as i32 <= codec::packed_bound(data.len() as i32).unwrap());
        assert_eq!(data, codec::unpack(&packed).unwrap());
    }
}

#[test]
fn a_run_of_one_byte_packs_small() {
    let expected = [
        0x40, 0x00, 0x00, 0x00, 0x1f, 0x61, 0x01, 0x00, 0x27, 0x50, 0x61, 0x61, 0x61, 0x61, 0x61,
    ];
    assert_eq!(expected.to_vec(), codec::pack(&[b'a'; 64], Effort::Fast).unwrap());
}

#[test]
fn higher_effort_packs_tighter() {
    let data = sentences(5000);
    assert_eq!(80, codec::pack(&data, Effort::Fast).unwrap().len());
    assert_eq!(78, codec::pack(&data, Effort::High).unwrap().len());
    assert_eq!(78, codec::pack(&data, Effort::Max).unwrap().len());
}

#[test]
fn nothing_packs_to_its_header_alone() {
    assert_eq!(vec![0, 0, 0, 0], codec::pack(&[], Effort::Fast).unwrap());
    assert!(codec::unpack(&[0, 0, 0, 0]).unwrap().is_empty());
}

#[test]
fn the_bound_covers_the_header() {
    assert_eq!(20, codec::packed_bound(0).unwrap());
    assert_eq!(5039, codec::packed_bound(5000).unwrap());
    let e = codec::packed_bound(-1).unwrap_err();
    assert!(e.is("System.ArgumentOutOfRangeException"));
    assert_eq!(Some("length"), e.param_name());
}

#[test]
fn a_short_header_is_refused() {
    let e = codec::unpack(&[1, 0, 0]).unwrap_err();
    assert!(e.is("System.IO.InvalidDataException"));
    assert_eq!("A packed blob starts with its length.", e.message());
}

#[test]
fn a_truncated_block_is_refused() {
    let mut packed = codec::pack(&sentences(2000), Effort::Fast).unwrap();
    packed.truncate(packed.len() - 3);
    assert!(codec::unpack(&packed).unwrap_err().is("System.IO.InvalidDataException"));
}

#[test]
fn a_header_that_claims_too_much_is_refused() {
    let mut packed = codec::pack(&sentences(10), Effort::Fast).unwrap();
    packed[0] = 12;
    let e = codec::unpack(&packed).unwrap_err();
    assert_eq!("The blob holds 10 bytes, not the 12 its header says.", e.message());
}

// NullIsRefused: Rust's slices are never null; the bridge refused null, and went with it.

#[test]
fn checksums_are_xx_hash() {
    assert_eq!(0xEF46_DB37_51D8_E999, codec::checksum(&[]));
    assert_eq!(0x1309_9D40_D095_B684, codec::checksum(&[0x41]));
    assert_eq!(0x02CC_5D05, codec::short_checksum(&[], 0));
    assert_eq!(0xE4FD_A1C1, codec::short_checksum(&[b'a'; 16], 0x9E37_79B1));
}

#[test]
fn checksums_tell_blobs_apart() {
    let mut data = noise(500, 3);
    let before = codec::checksum(&data);
    data[250] ^= 1;
    assert_ne!(before, codec::checksum(&data));
}

//! tests/Stash.Tests/StoreTests.cs and its ListLogger.cs, translated to Rust (CodeCoreMorph,
