use std::sync::{Arc, Mutex};

use codecoremorph_runtime::logging::{EventId, LogLevel, Logger, LoggerFactory};
use codecoremorph_runtime::{Exception, Result};
use stash_rs::codec;
use stash_rs::effort::Effort;
use stash_rs::store::Store;

#[derive(Clone, Debug)]
struct Logged {
    category: String,
    level: LogLevel,
    event: EventId,
    message: String,
    exception: Option<Exception>,
}

impl Logged {
    fn line(&self) -> String {
        format!("{:?} {} {}", self.level, self.event.id, self.message)
    }
}

type Sink = Arc<Mutex<Vec<Logged>>>;

/// A logger that keeps what it logs, from `min_level` up.
struct ListLogger {
    category: String,
    sink: Sink,
    min_level: Mutex<LogLevel>,
}

impl ListLogger {
    fn new(category: &str, sink: Sink, min_level: LogLevel) -> Arc<ListLogger> {
        Arc::new(ListLogger { category: category.to_string(), sink, min_level: Mutex::new(min_level) })
    }

    fn of_store() -> Arc<ListLogger> {
        ListLogger::new("Stash.Store", Sink::default(), LogLevel::Trace)
    }

    fn set_min_level(&self, level: LogLevel) {
        *self.min_level.lock().unwrap() = level;
    }

    fn logged(&self) -> Vec<Logged> {
        self.sink.lock().unwrap().clone()
    }

    fn lines(&self) -> Vec<String> {
        self.logged().iter().map(Logged::line).collect()
    }
}

impl Logger for ListLogger {
    fn is_enabled(&self, level: LogLevel) -> Result<bool> {
        Ok(level >= *self.min_level.lock().unwrap())
    }

    fn log(
        &self,
        level: LogLevel,
        event: &EventId,
        message: &str,
        exception: Option<&Exception>,
    ) -> Result<()> {
        if self.is_enabled(level)? {
            self.sink.lock().unwrap().push(Logged {
                category: self.category.clone(),
                level,
                event: event.clone(),
                message: message.to_string(),
                exception: exception.cloned(),
            });
        }
        Ok(())
    }
}

/// A factory of `ListLogger`s that share one list.
#[derive(Default)]
struct ListLoggerFactory {
    sink: Sink,
    categories: Mutex<Vec<String>>,
}

impl LoggerFactory for ListLoggerFactory {
    fn create_logger(&self, category: &str) -> Result<Arc<dyn Logger>> {
        self.categories.lock().unwrap().push(category.to_string());
        Ok(ListLogger::new(category, self.sink.clone(), LogLevel::Debug))
    }
}

#[test]
fn what_is_put_comes_back() {
    let store = Store::default();
    store.put("greeting", b"hello, hello, hello, hello").unwrap();
    store.put("empty", &[]).unwrap();
    assert_eq!(b"hello, hello, hello, hello".to_vec(), store.get("greeting").unwrap());
    assert!(store.get("empty").unwrap().is_empty());
    assert_eq!(2, store.count());
}

#[test]
fn packed_bytes_follow_puts_and_removes() {
    let store = Store::default();
    store.put("a", &[b'a'; 64]).unwrap();
    assert_eq!(15, store.packed_bytes());
    store.put("a", &[]).unwrap();
    assert_eq!(4, store.packed_bytes());
    assert!(store.remove("a").unwrap());
    assert_eq!(0, store.packed_bytes());
    assert!(!store.remove("a").unwrap());
}

#[test]
fn a_missing_key_throws() {
    let store = Store::default();
    let e = store.get("nope").unwrap_err();
    assert!(e.is("System.Collections.Generic.KeyNotFoundException"));
    assert_eq!("No blob is stored under 'nope'.", e.message());
    // A null key: Rust's strings are never null; the bridge refused null, and went with it.
}

#[test]
fn each_put_is_logged_at_debug() {
    let logger = ListLogger::of_store();
    let store = Store::new(Some(logger.clone()), Effort::Fast);
    store.put("a", &[b'a'; 64]).unwrap();
    store.put("b", b"b").unwrap();
    assert_eq!(vec!["Debug 0 Stored a: 64 bytes in 15", "Debug 0 Stored b: 1 bytes in 6"], logger.lines());
    assert_eq!("Stash.Store", logger.logged()[0].category);
}

#[test]
fn a_failed_checksum_is_logged_and_thrown() {
    let logger = ListLogger::of_store();
    let store = Store::new(Some(logger.clone()), Effort::High);
    store.put("x", b"some bytes, some bytes").unwrap();
    let (packed, sum) = store.export("x").unwrap();
    store.import("y", &packed, sum + 1).unwrap();
    let e = store.get("y").unwrap_err();
    assert!(e.is("System.IO.InvalidDataException"));
    assert_eq!("The blob under 'y' fails its checksum.", e.message());
    let logged = logger.logged();
    let warning = logged.last().unwrap();
    assert_eq!(LogLevel::Warning, warning.level);
    assert_eq!(7, warning.event.id);
    assert_eq!(Some("ChecksumMismatch"), warning.event.name.as_deref());
    assert_eq!("Checksum mismatch for y", warning.message);
    assert_eq!(format!("Trace 0 Imported y ({} bytes)", packed.len()), logged[1].line());
}

#[test]
fn removals_are_logged_only_when_information_is() {
    let logger = ListLogger::of_store();
    logger.set_min_level(LogLevel::Warning);
    let store = Store::new(Some(logger.clone()), Effort::Fast);
    store.put("a", b"a").unwrap();
    store.remove("a").unwrap();
    assert!(logger.logged().is_empty());
    logger.set_min_level(LogLevel::Information);
    store.put("a", b"a").unwrap();
    store.put("b", b"b").unwrap();
    store.remove("a").unwrap();
    assert_eq!(vec!["Information 0 Removed a; 1 left"], logger.lines());
}

#[test]
fn a_factory_names_its_loggers_category() {
    let factory = ListLoggerFactory::default();
    let store = Store::create(Some(&factory), Effort::Max).unwrap();
    store.put("k", b"value value value value value").unwrap();
    assert_eq!(vec!["Stash.Store"], *factory.categories.lock().unwrap());
    let lines: Vec<String> = factory.sink.lock().unwrap().iter().map(Logged::line).collect();
    assert_eq!(vec!["Debug 0 Stored k: 29 bytes in 19"], lines);
    let e = Store::create(None, Effort::Fast).err().unwrap();
    assert_eq!(Some("factory"), e.param_name());
}

#[test]
fn a_blob_that_doesnt_unpack_is_logged_with_its_exception() {
    let logger = ListLogger::of_store();
    logger.set_min_level(LogLevel::Error);
    let store = Store::new(Some(logger.clone()), Effort::Fast);
    store.put("x", b"some bytes, some bytes, some bytes").unwrap();
    let (mut packed, sum) = store.export("x").unwrap();
    packed.truncate(packed.len() - 3);
    store.import("cut", &packed, sum).unwrap();
    assert!(store.get("cut").unwrap_err().is("System.IO.InvalidDataException"));
    let logged = logger.logged();
    assert_eq!(1, logged.len());
    assert_eq!(LogLevel::Error, logged[0].level);
    assert_eq!("Blob cut doesn't unpack", logged[0].message);
    let exception = logged[0].exception.as_ref().unwrap();
    assert!(exception.is("System.IO.InvalidDataException"));
    assert_eq!("The blob's LZ4 block is corrupt.", exception.message());
}

#[test]
fn exports_are_copies() {
    let store = Store::default();
    store.put("a", b"abcabcabcabc").unwrap();
    let (mut packed, sum) = store.export("a").unwrap();
    packed[4] ^= 0xff;
    assert_eq!(b"abcabcabcabc".to_vec(), store.get("a").unwrap());
    assert_eq!(codec::checksum(b"abcabcabcabc"), sum);
}
